/// One registry row (`CapabilityMeta`).
class CapabilityMeta {
  const CapabilityMeta({
    required this.id,
    required this.key,
    this.legacy,
    required this.group,
    required this.tier,
    required this.risk,
    required this.defaults,
    required this.core,
    required this.approval,
    required this.limits,
    required this.pos,
    required this.isProtected,
    required this.en,
    required this.ar,
    this.hintEn,
    this.hintAr,
  });
  final int id;
  final String key;
  final String? legacy;
  final String group;
  final String tier;
  final String risk;
  final List<String> defaults;
  final List<String> core;
  final bool approval;
  final List<String> limits;
  final bool pos;
  final bool isProtected;
  final String en;
  final String ar;
  final String? hintEn;
  final String? hintAr;

  /// The label in [lang] (`en`/`ar`).
  String label(String lang) => lang.startsWith('ar') ? ar : en;

  /// The hint in [lang], if any.
  String? hint(String lang) => lang.startsWith('ar') ? hintAr : hintEn;
}

