/// A capability group (`CAPABILITY_GROUPS`).
class CapabilityGroup {
  const CapabilityGroup({
    required this.key,
    required this.en,
    required this.ar,
  });
  final String key;
  final String en;
  final String ar;
  String label(String lang) => lang.startsWith('ar') ? ar : en;
}

