/// The org modules (PS-2): `pos` = selling, catalog, stock and their reports;
/// `dawam` = attendance, roster, payroll.
abstract final class OrgModule {
  static const String pos = 'pos';
  static const String dawam = 'dawam';

  /// Every module: what a platform user with no org pinned sees (`ALL_MODULES`).
  static const List<String> all = <String>['pos', 'dawam'];
}
